import sys

import pytest


def test_teardown_request_reverse_order_and_exception(app, client):
    app.config["PROPAGATE_EXCEPTIONS"] = False
    view_exc = ValueError("view error")
    calls = []

    @app.teardown_request
    def first(exc):
        calls.append(("first", exc))

    @app.teardown_request
    def second(exc):
        calls.append(("second", exc))

    @app.teardown_request
    def third(exc):
        calls.append(("third", exc))

    @app.route("/")
    def index():
        raise view_exc

    response = client.get("/")
    assert response.status_code == 500
    assert calls == [
        ("third", view_exc),
        ("second", view_exc),
        ("first", view_exc),
    ]
    assert all(exc is view_exc for _, exc in calls)


def test_teardown_request_continues_after_error(app, client):
    app.config["PROPAGATE_EXCEPTIONS"] = False
    view_exc = ValueError("view error")
    teardown_exc = RuntimeError("teardown error")
    calls = []

    @app.teardown_request
    def first(exc):
        calls.append(("first", exc))

    @app.teardown_request
    def second(exc):
        calls.append(("second", exc))
        raise teardown_exc

    @app.teardown_request
    def third(exc):
        calls.append(("third", exc))

    @app.route("/")
    def index():
        raise view_exc

    if sys.version_info >= (3, 11):
        with pytest.raises(
            ExceptionGroup, match="Errors during context teardown"
        ) as exc_info:
            client.get("/")

        assert calls == [
            ("third", view_exc),
            ("second", view_exc),
            ("first", view_exc),
        ]
        assert all(exc is view_exc for _, exc in calls)
        assert len(exc_info.value.exceptions) == 1
        req_group = exc_info.value.exceptions[0]
        assert isinstance(req_group, ExceptionGroup)
        assert req_group.message == "Errors during request teardown"
        assert req_group.exceptions == (teardown_exc,)
    else:
        with pytest.raises(RuntimeError, match="teardown error") as exc_info:
            client.get("/")

        assert calls == [
            ("third", view_exc),
            ("second", view_exc),
            ("first", view_exc),
        ]
        assert all(exc is view_exc for _, exc in calls)
        assert exc_info.value is teardown_exc

import { Hono } from '../../hono'
import { MESSAGE_MATCHER_IS_ALREADY_BUILT } from '../../router'

describe('Default Hono() router selection with SmartRouter', () => {
  it('uses RegExpRouter when only ordinary routes are registered', async () => {
    const app = new Hono()
    app.get('/', (c) => c.text('root'))
    app.get('/users/:id', (c) => c.text(`user:${c.req.param('id')}`))
    app.post('/posts', (c) => c.text('created'))

    expect(app.router.name).toBe('SmartRouter')

    const res1 = await app.request('/')
    expect(res1.status).toBe(200)
    expect(await res1.text()).toBe('root')
    expect(app.router.name).toBe('SmartRouter + RegExpRouter')

    const res2 = await app.request('/users/42')
    expect(res2.status).toBe(200)
    expect(await res2.text()).toBe('user:42')
  })

  it('falls back to TrieRouter when a route RegExpRouter cannot handle is registered and answers requests correctly', async () => {
    const app = new Hono()
    app.get('/hello', (c) => c.text('hello'))
    app.get('/files/:name{.*}', (c) => c.text(`file:${c.req.param('name')}`))

    expect(app.router.name).toBe('SmartRouter')

    const res1 = await app.request('/hello')
    expect(res1.status).toBe(200)
    expect(await res1.text()).toBe('hello')
    expect(app.router.name).toBe('SmartRouter + TrieRouter')

    const res2 = await app.request('/files/dir/readme.md')
    expect(res2.status).toBe(200)
    expect(await res2.text()).toBe('file:dir/readme.md')
  })

  it('throws an error when adding a route after the first request has been handled', async () => {
    const app = new Hono()
    app.get('/first', (c) => c.text('first'))

    const res = await app.request('/first')
    expect(res.status).toBe(200)
    expect(await res.text()).toBe('first')
    expect(app.router.name).toBe('SmartRouter + RegExpRouter')

    expect(() => {
      app.get('/second', (c) => c.text('second'))
    }).toThrowError(new Error(MESSAGE_MATCHER_IS_ALREADY_BUILT))
  })
})

